    'blazer': 'Blazer',
    'blazers': 'Blazer',
    'coat': 'Coat',
    'coats': 'Coat',
    'sweater': 'Sweater',
    'sweaters': 'Sweater',
    'cardigan': 'Cardigan',
    'cardigans': 'Cardigan',
    'shoes': 'Shoes',
