/**
 * Saves a base64-encoded image to disk as a PNG file
 *
 * @param base64Data - Base64 image data (with or without data URL prefix)
 * @param filename - Name of the file to save
 * @returns Relative public URL path to the saved image
 * @throws Error if file save fails
 */
function saveBase64Image(base64Data: string, filename: string): string {
  // Strip data URL prefix if present (e.g., "data:image/png;base64,")
  const base64Content = base64Data.includes(',')
    ? base64Data.split(',')[1]
    : base64Data;

  // Construct absolute path to the public/generated-images directory
  const publicDir = path.join(process.cwd(), 'public', 'generated-images');
  ensureDirectoryExists(publicDir);

  const filePath = path.join(publicDir, filename);

  // Convert base64 to buffer and write to file
  const imageBuffer = Buffer.from(base64Content, 'base64');
  fs.writeFileSync(filePath, imageBuffer);

  console.log('[API] Saved image to:', filePath);

  // Return public URL path (relative)
  return `/generated-images/${filename}`;
}

/**
 * POST handler for image generation
 *
 * Request body:
 * {
 *   description: string,
 *   style?: {
 *     photographyStyle?: string,
 *     composition?: string,
 *     lighting?: string,
 *     aestheticContext?: string
 *   }
 * }
 *
 * Response on success:
 * {
 *   success: true,
 *   imageUrl: string,        // Public URL path (e.g., /generated-images/outfit-1732800000000.png)
 *   imageBase64: string,      // Base64-encoded image data
 *   error?: undefined,
 *   message?: undefined
 * }
 *
 * Response on failure:
 * {
 *   success: false,
 *   imageUrl?: undefined,
 *   imageBase64?: undefined,
 *   error: string,
 *   message: string
 * }
 */
export async function POST(request: NextRequest) {
  const startTime = Date.now();

  try {
    // Get client IP for rate limiting
    const clientIP = getClientIP(request);

    console.log('[API] Image generation request received from IP:', clientIP);

    // Check rate limiting
    if (isRateLimited(clientIP)) {
      console.warn('[API] Rate limit exceeded for IP:', clientIP);
      return NextResponse.json(
        {
          success: false,
          error: 'RATE_LIMITED',
          message: 'Too many requests. Please wait a minute before trying again.',
        },
        {
          status: 429,
          headers: {
            'Retry-After': '60',
          },
        }
      );
    }

    // Check if OPENROUTER_API_KEY is configured
    const apiKey = process.env.OPENROUTER_API_KEY;
    if (!apiKey) {
      console.error('[API] OPENROUTER_API_KEY not configured');
      return NextResponse.json(
        {
          success: false,
          error: 'SERVICE_UNAVAILABLE',
          message: 'Image generation service is not configured. Please contact support.',
        },
        { status: 503 }
      );
    }

    // Parse request body
    let body: ImageGenerationRequest;
    try {
      body = await request.json();
    } catch (error) {
      console.error('[API] Invalid JSON in request body:', error);
      return NextResponse.json(
        {
          success: false,
          error: 'INVALID_REQUEST',
          message: 'Invalid request format',
        },
        { status: 400 }
      );
    }

    // Validate request body
    const { description, style, referenceImage, secondaryReferenceImage, generationType, flatLayItems, occasionContext, backgroundStyle, userAesthetic, imageConfig } = body;

    // Flat-lay and hybrid-flat-lay generation require items instead of description
    if (generationType === 'flat-lay' || generationType === 'hybrid-flat-lay') {
      if (!flatLayItems || !Array.isArray(flatLayItems) || flatLayItems.length === 0) {
        console.error('[API] Missing or invalid items for flat-lay generation');
        return NextResponse.json(
          {
            success: false,
            error: 'INVALID_ITEMS',
            message: 'At least one item is required for flat-lay generation',
          },
          { status: 400 }
        );
      }
    } else if (!description || typeof description !== 'string' || description.trim() === '') {
      console.error('[API] Missing or invalid description');
      return NextResponse.json(
        {
          success: false,
          error: 'INVALID_DESCRIPTION',
          message: 'Outfit description is required',
        },
        { status: 400 }
      );
    }

    // Validate description length (3000 chars for fitting-model, 1000 for outfit)
    // Skip validation for flat-lay and hybrid-flat-lay since they use items instead of description
    if (generationType !== 'flat-lay' && generationType !== 'hybrid-flat-lay') {
      const maxDescriptionLength = (generationType === 'fitting-model' || generationType === 'try-on' || generationType === 'try-on-dual') ? 3000 : 1000;
      if (description && description.length > maxDescriptionLength) {
        console.error('[API] Description too long:', description.length);
        return NextResponse.json(
          {
            success: false,
            error: 'DESCRIPTION_TOO_LONG',
            message: `Description is too long. Please keep it under ${maxDescriptionLength} characters.`,
          },
          { status: 400 }
        );
      }
    }

    // Validate referenceImage format when provided with fitting-model, try-on, or try-on-dual generation
    if ((generationType === 'fitting-model' || generationType === 'try-on' || generationType === 'try-on-dual') && referenceImage) {
      if (typeof referenceImage !== 'string' || referenceImage.trim() === '') {
        console.error('[API] Invalid reference image for', generationType, 'generation');
        return NextResponse.json(
          {
            success: false,
            error: 'INVALID_REFERENCE_IMAGE',
            message: 'Reference image must be a valid string',
          },
          { status: 400 }
        );
      }

      if (!referenceImage.startsWith('data:image/')) {
        console.error('[API] Invalid reference image format');
        return NextResponse.json(
          {
            success: false,
            error: 'INVALID_REFERENCE_IMAGE_FORMAT',
            message: 'Reference image must be a base64 data URL (e.g., data:image/jpeg;base64,...)',
          },
          { status: 400 }
        );
      }
    }

    // Validate that try-on and try-on-dual generation require a reference image
    if ((generationType === 'try-on' || generationType === 'try-on-dual') && !referenceImage) {
      console.error('[API] Missing reference image for', generationType, 'generation');
      return NextResponse.json(
        {
          success: false,
          error: 'MISSING_REFERENCE_IMAGE',
          message: 'Reference image (fitting model) is required for try-on generation',
        },
        { status: 400 }
      );
    }

    // Validate secondaryReferenceImage format when provided (required for try-on-dual)
    if (generationType === 'try-on-dual') {
      if (!secondaryReferenceImage) {
        console.error('[API] Missing secondary reference image for try-on-dual generation');
        return NextResponse.json(
          {
            success: false,
            error: 'MISSING_SECONDARY_REFERENCE_IMAGE',
            message: 'Secondary reference image (flat-lay) is required for try-on-dual generation',
          },
          { status: 400 }
        );
      }

      if (typeof secondaryReferenceImage !== 'string' || !secondaryReferenceImage.startsWith('data:image/')) {
        console.error('[API] Invalid secondary reference image format');
        return NextResponse.json(
          {
            success: false,
            error: 'INVALID_SECONDARY_REFERENCE_IMAGE_FORMAT',
            message: 'Secondary reference image must be a base64 data URL (e.g., data:image/jpeg;base64,...)',
          },
          { status: 400 }
        );
      }
    }

    console.log('[API] Generating image:', {
      descriptionLength: description?.length || 0,
      style: style || 'default',
      generationType: generationType || 'outfit',
      hasReferenceImage: !!referenceImage,
      hasSecondaryReferenceImage: !!secondaryReferenceImage,
      flatLayItemCount: flatLayItems?.length || 0,
      backgroundStyle: backgroundStyle || 'auto',
      userAesthetic: userAesthetic || 'none',
      imageConfig: imageConfig || 'default',
    });

    // Create image client and generate image
    const imageClient = new OpenRouterImageClient(apiKey);

    // Route to appropriate generation method based on generationType
    let result;
    if (generationType === 'hybrid-flat-lay' && flatLayItems) {
      // Hybrid flat-lay: AI background + real product images
      const hybridResult = await generateHybridFlatLayWithFallback(
        {
          items: flatLayItems,
          backgroundStyle: backgroundStyle as BackgroundStyle | undefined,
          userAesthetic: userAesthetic as UserAesthetic | undefined,
          occasionContext: occasionContext,
        },
        apiKey
      );

      // Convert hybrid response to standard ImageGenerationResponse format
      result = {
        success: hybridResult.success,
        imageBase64: hybridResult.imageBase64,
        imageUrl: hybridResult.imageUrl,
        error: hybridResult.error,
        message: hybridResult.message,
        metadata: {
          model: 'hybrid-flat-lay',
          generatedAt: new Date().toISOString(),
          prompt: `Hybrid flat-lay with ${hybridResult.processedProducts.length} products`,
        },
      };
    } else if (generationType === 'flat-lay' && flatLayItems) {
      result = await imageClient.generateFlatLayImage({
        items: flatLayItems,
        occasionContext: occasionContext,
        totalItems: flatLayItems.length,
      });
    } else if (generationType === 'fitting-model' && referenceImage) {
      result = await imageClient.generateFittingModelImage(description, referenceImage);
    } else if (generationType === 'try-on-dual' && referenceImage && secondaryReferenceImage) {
      // Try-on with dual reference: fitting model (IMAGE 1) + flat-lay (IMAGE 2)
      result = await imageClient.generateTryOnWithDualReference(description, referenceImage, secondaryReferenceImage);
    } else if (generationType === 'try-on' && referenceImage) {
      // Try-on with single reference: fitting model only (fallback mode)
      result = await imageClient.generateFittingModelImage(description, referenceImage);
    } else {
      result = await imageClient.generateOutfitImage(description, style);
    }

    const duration = Date.now() - startTime;
    console.log('[API] Image generation completed in', duration, 'ms', {
      success: result.success,
      error: result.error || 'none',
    });

    // Return response with appropriate status code
    if (result.success) {
      // Save image to disk and add imageUrl to response
      if (result.imageBase64) {
        try {
          const filename = generateImageFilename();
          const imageUrl = saveBase64Image(result.imageBase64, filename);
          const publicDir = path.join(process.cwd(), 'public', 'generated-images');
          const filePath = path.join(publicDir, filename);

          // Apply background removal for fitting-model, try-on, and try-on-dual images
          if (generationType === 'fitting-model' || generationType === 'try-on' || generationType === 'try-on-dual') {
            console.log('[API] Applying background removal for', generationType);
            const bgRemovalSuccess = await removeBackgroundFromFile(filePath, filePath);

            if (bgRemovalSuccess) {
              // Re-read the processed image and update base64
              const processedImageBuffer = fs.readFileSync(filePath);
              result.imageBase64 = `data:image/png;base64,${processedImageBuffer.toString('base64')}`;
              console.log('[API] Background removed successfully');

              // Apply auto-crop to ensure model fills the frame
              console.log('[API] Applying auto-crop for', generationType);
              const autoCropSuccess = await autoCropSubject(filePath, filePath);

              if (autoCropSuccess) {
                // Re-read the cropped image and update base64
                const croppedImageBuffer = fs.readFileSync(filePath);
                result.imageBase64 = `data:image/png;base64,${croppedImageBuffer.toString('base64')}`;
                console.log('[API] Auto-crop completed successfully');
              } else {
                console.warn('[API] Auto-crop failed, using image with background removed');
              }
            } else {
              console.warn('[API] Background removal failed, using original image');
            }
          }

          // Add imageUrl to the result
          result.imageUrl = imageUrl;

          console.log('[API] Image saved successfully:', imageUrl);
        } catch (saveError) {
          // Log error but don't fail the request - base64 is still available
          console.error('[API] Failed to save image to disk:', saveError);
          console.warn('[API] Continuing without imageUrl - base64 still available');
        }
      }

      return NextResponse.json(result, {
        status: 200,
        headers: {
          'Cache-Control': 'no-cache, no-store, must-revalidate',
        },
      });
    } else {
      // Determine status code based on error type
      let statusCode = 500;
      if (result.error === 'RATE_LIMITED') {
        statusCode = 429;
      } else if (result.error === 'INVALID_DESCRIPTION') {
        statusCode = 400;
      } else if (result.error === 'SERVICE_UNAVAILABLE') {
        statusCode = 503;
      }

      return NextResponse.json(result, {
        status: statusCode,
      });
    }
  } catch (error) {
    const duration = Date.now() - startTime;
    console.error('[API] Unexpected error during image generation:', error);
    console.error('[API] Error occurred after', duration, 'ms');

    return NextResponse.json(
      {
        success: false,
        error: 'INTERNAL_ERROR',
        message: 'An unexpected error occurred. Please try again later.',
      },
      { status: 500 }
    );
  }
}

/**
 * GET handler - not supported
 * Returns 405 Method Not Allowed
 */
export async function GET() {
  return NextResponse.json(
    {
      success: false,
      error: 'METHOD_NOT_ALLOWED',
      message: 'GET method is not supported. Use POST to generate images.',
    },
    { status: 405 }
  );
}

/**
 * OPTIONS handler for CORS preflight
 */
export async function OPTIONS() {
  return NextResponse.json(
    {},
    {
      status: 200,
      headers: {
        'Access-Control-Allow-Origin': '*',
        'Access-Control-Allow-Methods': 'POST, OPTIONS',
        'Access-Control-Allow-Headers': 'Content-Type',
      },
    }
  );
}

/**
 * Type definitions for image generation feature (Customer Journey Step 4)
 * Supports text-to-image generation for outfit visualization using OpenRouter's Gemini 2.5 Flash Image model
 */

/**
 * Background styles for hybrid flat-lay generation
 * Maps to different textured backgrounds that complement various fashion aesthetics
 */
export type BackgroundStyle =
  | 'white-clean'      // Pure white, minimal
  | 'marble-white'     // White marble texture, quiet-luxury
  | 'marble-grey'      // Grey marble texture, corporate-chic
  | 'wood-light'       // Light wood grain, natural
  | 'wood-dark'        // Dark wood grain, dark-academia
  | 'linen-natural'    // Natural linen texture, clean-girl
  | 'linen-grey';      // Grey linen texture, casual-chic

/**
 * User aesthetic preferences that map to background styles
 */
export type UserAesthetic =
  | 'clean-girl'
  | 'quiet-luxury'
  | 'corporate-chic'
  | 'dark-academia'
  | 'scandinavian-minimal'
  | 'casual-chic'
  | 'bohemian'
  | 'streetwear'
  | 'romantic';

/**
 * Configuration for OpenRouter image generation output
 * Controls aspect ratio and resolution of generated images
 */
export interface ImageConfig {
  /** Aspect ratio for generated image */
  aspect_ratio?: '1:1' | '2:3' | '3:2' | '3:4' | '4:3' | '4:5' | '5:4' | '9:16' | '16:9' | '21:9';
  /** Output image resolution */
  image_size?: '1K' | '2K' | '4K';
}

/**
 * Individual item in a flat-lay composition
 */
export interface FlatLayItem {
  /** Product name */
  name: string;
  /** Product category (e.g., 'Dress', 'Shoes') */
  category: string;
  /** Product color for prompt accuracy */
  color?: string;
  /** Optional detailed visual description */
  visualDescription?: string;
  /** Product SKU for tracking which actual product this item represents */
  sku?: string;
  /** Product thumbnail URL for composite image generation or validation */
  thumbnailUrl?: string;
  /** Whether this item passed visual consistency validation */
  isVisuallyConsistent?: boolean;
}

/**
 * Request payload for flat-lay image generation
 */
export interface FlatLayRequest {
  /** Array of recommended products */
  items: FlatLayItem[];
  /** Total item count for display */
  totalItems?: number;
  /** Optional occasion context (e.g., 'work outfit') */
  occasionContext?: string;
  /** Optional image generation configuration (aspect ratio, resolution) */
  imageConfig?: ImageConfig;
}

/**
 * Request payload for image generation API
 */
export interface ImageGenerationRequest {
  /** Description of the outfit to generate (fashion context extracted from conversation) */
  description: string;
  /** Optional style parameters for image generation */
  style?: {
    /** Photography style: 'professional', 'casual', 'studio', 'lifestyle' */
    photographyStyle?: string;
    /** Composition: 'full-body', 'flat-lay', 'mannequin', '3/4-view' */
    composition?: string;
    /** Lighting mood: 'natural', 'studio', 'soft', 'bright' */
    lighting?: string;
    /** Cultural context: 'thai-contemporary', 'minimalist', 'classic', 'modern' */
    aestheticContext?: string;
  };
  /**
   * Base64-encoded reference image for multimodal generation.
   * Must include data URL prefix (e.g., 'data:image/jpeg;base64,...').
   * Used for fitting model generation to enable accurate face-matching.
   */
  referenceImage?: string;
  /**
   * Type of image generation to perform.
   * - 'outfit': Standard outfit image generation (default)
   * - 'fitting-model': Fitting model generation with reference image for face-matching
   * - 'flat-lay': Flat-lay composition of recommended items (AI-only)
   * - 'hybrid-flat-lay': Hybrid flat-lay combining AI backgrounds with real product images
   * - 'try-on': Try-on generation showing outfit worn on user's fitting model
   * - 'try-on-dual': Try-on with dual image reference (fitting model + flat-lay outfit)
   */
  generationType?: 'outfit' | 'fitting-model' | 'flat-lay' | 'hybrid-flat-lay' | 'try-on' | 'try-on-dual';
  /**
   * Secondary reference image for dual-image generation (e.g., flat-lay image for try-on).
   * Must include data URL prefix (e.g., 'data:image/jpeg;base64,...').
   * Used in 'try-on-dual' mode to show the exact outfit items the model must wear.
   */
  secondaryReferenceImage?: string;
  /**
   * Items for flat-lay generation (required when generationType is 'flat-lay')
   */
  flatLayItems?: FlatLayItem[];
  /**
   * Occasion context for flat-lay generation
   */
  occasionContext?: string;
  /**
   * Background style for hybrid flat-lay generation
   */
  backgroundStyle?: BackgroundStyle;
  /**
   * User aesthetic preference for automatic background style mapping
   */
  userAesthetic?: UserAesthetic;
  /**
   * Optional image generation configuration (aspect ratio, resolution)
   */
  imageConfig?: ImageConfig;
}

/**
 * Response from image generation API
 */
export interface ImageGenerationResponse {
  /** URL to the generated image (if hosted) */
  imageUrl?: string;
  /** Base64-encoded image data (if returned inline) */
  imageBase64?: string;
  /** Metadata about the generated image */
  metadata?: {
    /** Model used for generation */
    model: string;
    /** Generation timestamp */
    generatedAt: string;
    /** Prompt used for generation */
    prompt?: string;
    /** Image dimensions */
    dimensions?: {
      width: number;
      height: number;
    };
  };
  /** Error message if generation failed */
  error?: string;
  /** User-friendly message for display */
  message?: string;
  /** Success flag */
  success: boolean;
}

/**
 * Props for LooksInspiration UI component
 */
export interface LooksInspirationProps {
  /** Outfit description used for generation */
  outfitDescription: string;
  /** URL to generated image */
  imageUrl?: string;
  /** Base64-encoded image data */
  imageBase64?: string;
  /** Loading state for image generation */
  isLoading?: boolean;
  /** Error message if generation failed */
  error?: string;
  /** Callback for retry button */
  onRetry?: () => void;
  /** Optional callback for "generate another" functionality */
  onGenerateAnother?: () => void;
  /** Optional callback for download functionality */
  onDownload?: () => void;
  /** Layout mode: 'portrait' (3:4) or 'flat-lay' (1:1 square) */
  displayMode?: 'portrait' | 'flat-lay';
  /** Items to display in flat-lay mode */
  recommendedItems?: FlatLayItem[];
  /** Optional custom header title */
  headerTitle?: string;
}

/**
 * Internal state for image generation in chat
 */
export interface ImageGenerationState {
  /** Whether image is currently being generated */
  isGenerating: boolean;
  /** Generated image URL */
  imageUrl?: string;
  /** Generated image base64 data */
  imageBase64?: string;
  /** Outfit description used for generation */
  outfitDescription?: string;
  /** Error message */
  error?: string;
}

/**
 * Processed product image with background removed
 */
export interface ProcessedProductImage {
  /** Original product SKU */
  sku: string;
  /** Product name for reference */
  name: string;
  /** Product category for layout positioning */
  category: string;
  /** Base64-encoded image with transparent background */
  imageBase64: string;
  /** Original image dimensions */
  originalDimensions: {
    width: number;
    height: number;
  };
  /** Whether processing was successful */
  success: boolean;
  /** Error message if processing failed */
  error?: string;
}

/**
 * Configuration for product image layout in composite
 */
export interface ProductLayoutConfig {
  /** X position (0-1 relative to canvas width) */
  x: number;
  /** Y position (0-1 relative to canvas height) */
  y: number;
  /** Rotation angle in degrees */
  rotation: number;
  /** Scale factor (1 = 100%) */
  scale: number;
  /** Z-index for layering */
  zIndex: number;
}

/**
 * Request for hybrid flat-lay generation
 */
export interface HybridFlatLayRequest {
  /** Products to include in the flat-lay */
  items: FlatLayItem[];
  /** Background style (or auto-detected from aesthetic) */
  backgroundStyle?: BackgroundStyle;
  /** User aesthetic preference for automatic background mapping */
  userAesthetic?: UserAesthetic;
  /** Occasion context for styling */
  occasionContext?: string;
  /** Canvas dimensions (default 1024x1024) */
  canvasDimensions?: {
    width: number;
    height: number;
  };
  /** Optional image generation configuration (aspect ratio, resolution) */
  imageConfig?: ImageConfig;
}

/**
 * Response from hybrid flat-lay generation
 */
export interface HybridFlatLayResponse {
  /** Whether generation was successful */
  success: boolean;
  /** Final composite image as base64 */
  imageBase64?: string;
  /** URL if saved to disk */
  imageUrl?: string;
  /** Background style used */
  backgroundStyle?: BackgroundStyle;
  /** Products that were successfully processed */
  processedProducts: string[];
  /** Products that failed processing (excluded from composite) */
  failedProducts: string[];
  /** Error message if generation failed */
  error?: string;
  /** Human-readable message */
  message?: string;
}

