}

/**
 * Build a comprehensive system prompt for occasion-based flat-lay generation.
 *
 * Takes a user request with an occasion preset and interpolates all configuration
 * values into a structured prompt that guides the AI to:
 * 1. Analyze user context
 * 2. Curate outfit items appropriate for the occasion
 * 3. Generate a flat-lay image prompt
 */
export function buildOccasionFlatLaySystemPrompt(request: OccasionFlatLayRequest): string {
  const config = OCCASION_PRESET_CONFIGS[request.occasion];

  const userName = request.userName || 'Fashionista';
  const userAge = request.userAge || 'not specified';
  const stylePreferences =
    request.stylePreferences && request.stylePreferences.length > 0
      ? request.stylePreferences.join(', ')
      : 'versatile and trendy';
  const hasReferenceImage = request.hasReferenceImage || false;

  return `You are OOTDay, an AI fashion styling assistant. Your task is to curate a complete outfit and generate a flat-lay image prompt.

## User Profile
- Name: ${userName}
- Age: ${userAge}
- Style Preferences: ${stylePreferences}
- Has Reference Image: ${hasReferenceImage}

## Selected Occasion: ${config.label} ${config.emoji}
- Occasion Types: ${config.occasionTypes.join(', ')}
- Formality Range: ${config.formalityRange.min}-${config.formalityRange.max} out of 10
- Recommended Color Palette: ${config.defaultColorPalette.join(', ')}
- Key Pieces to Consider: ${config.keyPieces.join(', ')}

## Your Task

### Step 1: Analyze User Context
Consider the user's age, style preferences, and the selected occasion to determine the most appropriate outfit direction.

### Step 2: Curate Outfit Items
Select a minimum of 3 items (no maximum) from women's clothing that form a cohesive outfit. Each item must be:
- Appropriate for the occasion's formality range
- Compatible with the user's style preferences
- Color-coordinated using the recommended palette
- IMPORTANT: No duplicate item categories (e.g., don't pick two tops)

For each item, provide:
- Item name (generic, no brand names)
- Category (e.g., Top, Bottom, Dress, Shoes, Bag, Accessory)
- Color
- Brief visual description

### Step 3: Generate Flat-Lay Image Prompt
After curating the outfit, write a detailed image generation prompt that follows these MANDATORY specifications:

**Required Elements:**
- Studio white/light background
- Overhead (bird's-eye view) camera angle
- 1:1 square aspect ratio
- Professional flat-lay photography style
- Each item clearly visible and well-spaced
- Soft, diffused lighting with no harsh shadows

**Forbidden Elements:**
- NO text, labels, or watermarks of any kind
- NO colored or patterned backgrounds
- NO human body parts (hands, feet, etc.)
- NO unrelated props or decorations
- NO brand logos or tags

### Step 4: Output Format
Respond in this exact format:

CURATED_ITEMS:
1. [Item Name] | [Category] | [Color] | [Visual Description]
2. [Item Name] | [Category] | [Color] | [Visual Description]
3. [Item Name] | [Category] | [Color] | [Visual Description]
(continue for all items)

IMAGE_PROMPT:
A high-resolution, studio-lit flat-lay photograph showing [number] fashion items arranged as a coordinated ${config.label.toLowerCase()} outfit on a pristine white surface. The items are: [describe each item with color and style]. The composition uses balanced spacing with each piece clearly visible and proportionally sized. Photographed from directly overhead with soft, diffused three-point lighting that eliminates harsh shadows and preserves accurate colors. Professional e-commerce product photography quality with sharp focus across all items. Clean, minimal styling. Square 1:1 format.`;
}

/**
 * Occasion Flat-Lay Orchestration Service
 * Orchestrates AI curation + flat-lay image generation for occasion presets
 */

import type { OccasionFlatLayRequest, OccasionFlatLayResponse, FlatLayItem } from '../types/image-types';
import { buildOccasionFlatLaySystemPrompt } from '../prompts/occasion-flat-lay-prompt';
import { OpenRouterImageClient } from './image-generation-service';

const LOG_PREFIX = '[OccasionFlatLay]';

/**
 * OpenRouter chat completion configuration for AI curation
 * Uses a text model (not image generation model) for outfit curation
 */
const CURATION_CONFIG = {
  baseUrl: 'https://openrouter.ai/api/v1',
  model: 'google/gemini-3-flash-preview',  // Text model for curation (same as ai-chat-service)
  timeout: 30000,
  maxTokens: 2048,
};

/**
 * Parse AI response to extract curated items and image prompt
 */
export function parseAIResponse(responseText: string): {
  curatedItems: FlatLayItem[];
  imagePrompt: string | null;
} {
  const curatedItems: FlatLayItem[] = [];
  let imagePrompt: string | null = null;

  // Extract CURATED_ITEMS section
  const itemsMatch = responseText.match(/CURATED_ITEMS:\s*\n([\s\S]*?)(?=IMAGE_PROMPT:|$)/i);
  if (itemsMatch) {
    const itemLines = itemsMatch[1].trim().split('\n').filter(line => line.trim());
    for (const line of itemLines) {
      // Parse: "1. Item Name | Category | Color | Visual Description"
      const match = line.match(/^\d+\.\s*(.+?)\s*\|\s*(.+?)\s*\|\s*(.+?)\s*\|\s*(.+)$/);
      if (match) {
        curatedItems.push({
          name: match[1].trim(),
          category: match[2].trim(),
          color: match[3].trim(),
          visualDescription: match[4].trim(),
        });
      }
    }
  }

  // Extract IMAGE_PROMPT section
  const promptMatch = responseText.match(/IMAGE_PROMPT:\s*\n([\s\S]*?)$/i);
  if (promptMatch) {
    imagePrompt = promptMatch[1].trim();
  }

  return { curatedItems, imagePrompt };
}

/**
 * Call OpenRouter chat completion for AI outfit curation
 */
async function callAICuration(
  systemPrompt: string,
  apiKey: string
): Promise<string> {
  const controller = new AbortController();
  const timeoutId = setTimeout(() => controller.abort(), CURATION_CONFIG.timeout);

  try {
    const response = await fetch(`${CURATION_CONFIG.baseUrl}/chat/completions`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        Authorization: `Bearer ${apiKey}`,
        'HTTP-Referer': 'https://ootday.com',
        'X-Title': 'OOTDay Fashion Assistant',
      },
      body: JSON.stringify({
        model: CURATION_CONFIG.model,
        messages: [
          { role: 'system', content: systemPrompt },
          { role: 'user', content: 'Please curate an outfit for me based on the occasion and my profile, then generate the flat-lay image prompt.' },
        ],
        max_tokens: CURATION_CONFIG.maxTokens,
      }),
      signal: controller.signal,
    });

    clearTimeout(timeoutId);

    if (!response.ok) {
      const errorData = await response.json().catch(() => ({}));
      throw new Error(
        `OpenRouter API error: ${response.status} - ${(errorData as any).error?.message || response.statusText}`
      );
    }

    const data = await response.json();
    const content = (data as any).choices?.[0]?.message?.content;

    if (!content || typeof content !== 'string') {
      throw new Error('Empty or invalid response from AI curation');
    }

    return content;
  } catch (error) {
    clearTimeout(timeoutId);
    if (error instanceof Error && error.name === 'AbortError') {
      throw new Error('AI curation request timed out');
    }
    throw error;
  }
}

/**
 * Main orchestration function: AI curation -> image prompt extraction -> image generation
 */
export async function generateOccasionFlatLay(
  request: OccasionFlatLayRequest,
  apiKey: string
): Promise<OccasionFlatLayResponse> {
  console.log(`${LOG_PREFIX} Starting generation for occasion: ${request.occasion}`);

  try {
    // Step 1: Build system prompt
    const systemPrompt = buildOccasionFlatLaySystemPrompt(request);
    console.log(`${LOG_PREFIX} System prompt built (${systemPrompt.length} chars)`);

    // Step 2: Call AI for outfit curation + image prompt
    console.log(`${LOG_PREFIX} Calling AI curation...`);
    const aiResponse = await callAICuration(systemPrompt, apiKey);
    console.log(`${LOG_PREFIX} AI curation response received (${aiResponse.length} chars)`);

    // Step 3: Parse AI response
    const { curatedItems, imagePrompt } = parseAIResponse(aiResponse);
    console.log(`${LOG_PREFIX} Parsed ${curatedItems.length} curated items`);

    if (!imagePrompt) {
      console.error(`${LOG_PREFIX} No image prompt found in AI response`);
      return {
        success: false,
        curatedItems,
        error: 'AI_PARSE_ERROR',
        message: 'Could not extract image prompt from AI response',
      };
    }

    if (curatedItems.length === 0) {
      console.warn(`${LOG_PREFIX} No curated items parsed, but image prompt available`);
    }

    console.log(`${LOG_PREFIX} Image prompt extracted (${imagePrompt.length} chars)`);

    // Step 4: Generate flat-lay image using the extracted prompt
    console.log(`${LOG_PREFIX} Generating flat-lay image...`);
    const imageClient = new OpenRouterImageClient(apiKey);
    const imageResult = await imageClient.generateOutfitImage(imagePrompt);

    if (!imageResult.success) {
      console.error(`${LOG_PREFIX} Image generation failed:`, imageResult.error);
      return {
        success: false,
        curatedItems,
        imagePrompt,
        error: imageResult.error || 'IMAGE_GENERATION_FAILED',
        message: imageResult.message || 'Failed to generate flat-lay image',
      };
    }

    console.log(`${LOG_PREFIX} Flat-lay image generated successfully`);

    return {
      success: true,
      imageBase64: imageResult.imageBase64,
      imageUrl: imageResult.imageUrl,
      curatedItems,
      imagePrompt,
      message: 'Occasion flat-lay generated successfully',
    };
  } catch (error) {
    console.error(`${LOG_PREFIX} Error:`, error);
    const errorMessage = error instanceof Error ? error.message : 'Unknown error';
    return {
      success: false,
      error: 'GENERATION_ERROR',
      message: `Failed to generate occasion flat-lay: ${errorMessage}`,
    };
  }
}

