const mockGenerateRawFlatLay = vi.fn();

vi.mock('../../services/image-generation-service', () => ({
  OpenRouterImageClient: vi.fn().mockImplementation(() => ({
    generateRawFlatLay: mockGenerateRawFlatLay,
  })),
}));

